"""Simple API-key based authentication / role authorization."""


def resolve_role(db, headers):
    """Return the role (READ/WRITE/ADMIN) for the given request headers, or None."""
    key = None
    auth_header = headers.get("Authorization")
    if auth_header and auth_header.lower().startswith("bearer "):
        key = auth_header[7:].strip()
    if not key:
        key = headers.get("X-Api-Key")
    if not key:
        return None
    with db.lock:
        row = db.conn.execute("SELECT role FROM api_keys WHERE key=?", (key,)).fetchone()
    return row["role"] if row else None


def role_allows(role, required):
    """Check whether `role` satisfies the `required` access level."""
    if required == "READ":
        return role in ("READ", "WRITE", "ADMIN")
    if required == "WRITE":
        return role in ("WRITE", "ADMIN")
    return False

"""Core business logic: catalog CRUD, stock intake/adjustment with
optimistic concurrency, threshold configuration, alert evaluation and
audit history. All persistence goes through the shared Database lock.
"""
import json
import logging
import sqlite3
import uuid
from datetime import datetime, timezone

logger = logging.getLogger("inventory")


class NotFoundError(Exception):
    pass


class ValidationError(Exception):
    pass


class ConflictError(Exception):
    pass


def _now():
    return datetime.now(timezone.utc).isoformat()


def _new_id():
    return uuid.uuid4().hex


class InventoryService:
    def __init__(self, db, event_bus, metrics):
        self.db = db
        self.event_bus = event_bus
        self.metrics = metrics

    # ---------------------------------------------------------- warehouses
    def create_warehouse(self, name, location):
        if not name:
            raise ValidationError("name is required")
        wid, now = _new_id(), _now()
        with self.db.lock:
            self.db.conn.execute(
                "INSERT INTO warehouses(id,name,location,created_at) VALUES (?,?,?,?)",
                (wid, name, location, now),
            )
            self.db.conn.commit()
        return {"id": wid, "name": name, "location": location, "created_at": now}

    def get_warehouse(self, warehouse_id):
        with self.db.lock:
            row = self.db.conn.execute(
                "SELECT * FROM warehouses WHERE id=?", (warehouse_id,)
            ).fetchone()
        if not row:
            raise NotFoundError(f"warehouse {warehouse_id} not found")
        return dict(row)

    def list_warehouses(self):
        with self.db.lock:
            rows = self.db.conn.execute("SELECT id,name,location FROM warehouses").fetchall()
        return [dict(r) for r in rows]

    # ------------------------------------------------------------ products
    def create_product(self, sku, name, description):
        if not sku or not name:
            raise ValidationError("sku and name are required")
        pid, now = _new_id(), _now()
        with self.db.lock:
            try:
                self.db.conn.execute(
                    "INSERT INTO products(id,sku,name,description,created_at) VALUES (?,?,?,?,?)",
                    (pid, sku, name, description, now),
                )
                self.db.conn.commit()
            except sqlite3.IntegrityError:
                raise ConflictError(f"sku {sku} already exists")
        return {"id": pid, "sku": sku, "name": name, "description": description}

    def get_product(self, product_id):
        with self.db.lock:
            row = self.db.conn.execute(
                "SELECT * FROM products WHERE id=?", (product_id,)
            ).fetchone()
        if not row:
            raise NotFoundError(f"product {product_id} not found")
        return dict(row)

    def list_products(self):
        with self.db.lock:
            rows = self.db.conn.execute("SELECT id,sku,name FROM products").fetchall()
        return [dict(r) for r in rows]

    # ---------------------------------------------------------------- misc
    def _ensure_warehouse_product(self, warehouse_id, product_id):
        if not self.db.conn.execute(
            "SELECT 1 FROM warehouses WHERE id=?", (warehouse_id,)
        ).fetchone():
            raise NotFoundError(f"warehouse {warehouse_id} not found")
        if not self.db.conn.execute(
            "SELECT 1 FROM products WHERE id=?", (product_id,)
        ).fetchone():
            raise NotFoundError(f"product {product_id} not found")

    def _get_stock_row(self, warehouse_id, product_id):
        return self.db.conn.execute(
            "SELECT * FROM stock_items WHERE warehouse_id=? AND product_id=?",
            (warehouse_id, product_id),
        ).fetchone()

    def _effective_threshold(self, item_threshold):
        if item_threshold is not None:
            return item_threshold
        row = self.db.conn.execute(
            "SELECT default_threshold FROM global_threshold WHERE id=1"
        ).fetchone()
        return row["default_threshold"] if row else None

    # ------------------------------------------------------------- stock
    def add_stock(self, warehouse_id, product_id, quantity, threshold=None, actor="system", reason=None):
        if not warehouse_id or not product_id:
            raise ValidationError("warehouse_id and product_id are required")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValidationError("quantity must be a positive integer")
        if threshold is not None and (not isinstance(threshold, int) or threshold < 0):
            raise ValidationError("threshold must be a non-negative integer")
        now = _now()
        with self.db.lock:
            self._ensure_warehouse_product(warehouse_id, product_id)
            row = self._get_stock_row(warehouse_id, product_id)
            if row is None:
                new_qty, new_version, stored_threshold = quantity, 1, threshold
                self.db.conn.execute(
                    "INSERT INTO stock_items(warehouse_id,product_id,quantity,version,threshold,updated_at)"
                    " VALUES (?,?,?,?,?,?)",
                    (warehouse_id, product_id, new_qty, new_version, stored_threshold, now),
                )
            else:
                new_qty = row["quantity"] + quantity
                new_version = row["version"] + 1
                stored_threshold = threshold if threshold is not None else row["threshold"]
                self.db.conn.execute(
                    "UPDATE stock_items SET quantity=?, version=?, threshold=?, updated_at=?"
                    " WHERE warehouse_id=? AND product_id=?",
                    (new_qty, new_version, stored_threshold, now, warehouse_id, product_id),
                )
            self.db.conn.execute(
                "INSERT INTO stock_adjustments(id,warehouse_id,product_id,delta,resulting_quantity,"
                "reason,actor,created_at,idempotency_key) VALUES (?,?,?,?,?,?,?,?,NULL)",
                (_new_id(), warehouse_id, product_id, quantity, new_qty, reason or "STOCK_ADD", actor, now),
            )
            eff_threshold = self._effective_threshold(stored_threshold)
            self._evaluate_alert(warehouse_id, product_id, new_qty, eff_threshold)
            self.db.conn.commit()
            logger.info("stock added wh=%s product=%s qty=%s new_qty=%s", warehouse_id, product_id, quantity, new_qty)
        self.metrics.inc("stock_add_total")
        return {
            "warehouse_id": warehouse_id,
            "product_id": product_id,
            "quantity": new_qty,
            "version": new_version,
            "threshold": eff_threshold,
        }

    def adjust_stock(self, warehouse_id, product_id, delta, actor="system", reason=None):
        if not warehouse_id or not product_id:
            raise ValidationError("warehouse_id and product_id are required")
        if not isinstance(delta, int) or delta == 0:
            raise ValidationError("delta must be a non-zero integer")
        now = _now()
        with self.db.lock:
            self._ensure_warehouse_product(warehouse_id, product_id)
            row = self._get_stock_row(warehouse_id, product_id)
            if row is None:
                raise NotFoundError("stock item not found for given warehouse/product")
            new_qty = row["quantity"] + delta
            if new_qty < 0:
                raise ValidationError("insufficient stock: resulting quantity would be negative")
            new_version = row["version"] + 1
            cur = self.db.conn.execute(
                "UPDATE stock_items SET quantity=?, version=?, updated_at=?"
                " WHERE warehouse_id=? AND product_id=? AND version=?",
                (new_qty, new_version, now, warehouse_id, product_id, row["version"]),
            )
            if cur.rowcount != 1:
                raise ConflictError("concurrent modification detected, please retry")
            self.db.conn.execute(
                "INSERT INTO stock_adjustments(id,warehouse_id,product_id,delta,resulting_quantity,"
                "reason,actor,created_at,idempotency_key) VALUES (?,?,?,?,?,?,?,?,NULL)",
                (_new_id(), warehouse_id, product_id, delta, new_qty, reason or "ADJUST", actor, now),
            )
            eff_threshold = self._effective_threshold(row["threshold"])
            alert_triggered = self._evaluate_alert(warehouse_id, product_id, new_qty, eff_threshold)
            self.db.conn.commit()
            logger.info("stock adjusted wh=%s product=%s delta=%s new_qty=%s", warehouse_id, product_id, delta, new_qty)
        self.metrics.inc("stock_adjust_total")
        return {
            "warehouse_id": warehouse_id,
            "product_id": product_id,
            "quantity": new_qty,
            "version": new_version,
            "alert_triggered": alert_triggered,
        }

    def get_stock(self, warehouse_id, product_id):
        with self.db.lock:
            self._ensure_warehouse_product(warehouse_id, product_id)
            row = self._get_stock_row(warehouse_id, product_id)
            if not row:
                raise NotFoundError("stock item not found")
            eff = self._effective_threshold(row["threshold"])
        return {
            "warehouse_id": warehouse_id,
            "product_id": product_id,
            "quantity": row["quantity"],
            "threshold": eff,
            "version": row["version"],
            "updated_at": row["updated_at"],
        }

    def list_stock_by_product(self, product_id):
        with self.db.lock:
            if not self.db.conn.execute("SELECT 1 FROM products WHERE id=?", (product_id,)).fetchone():
                raise NotFoundError(f"product {product_id} not found")
            rows = self.db.conn.execute(
                "SELECT warehouse_id,quantity,threshold FROM stock_items WHERE product_id=?",
                (product_id,),
            ).fetchall()
            return [
                {"warehouse_id": r["warehouse_id"], "quantity": r["quantity"],
                 "threshold": self._effective_threshold(r["threshold"])}
                for r in rows
            ]

    def list_stock_by_warehouse(self, warehouse_id):
        with self.db.lock:
            if not self.db.conn.execute("SELECT 1 FROM warehouses WHERE id=?", (warehouse_id,)).fetchone():
                raise NotFoundError(f"warehouse {warehouse_id} not found")
            rows = self.db.conn.execute(
                "SELECT product_id,quantity,threshold FROM stock_items WHERE warehouse_id=?",
                (warehouse_id,),
            ).fetchall()
            return [
                {"product_id": r["product_id"], "quantity": r["quantity"],
                 "threshold": self._effective_threshold(r["threshold"])}
                for r in rows
            ]

    # -------------------------------------------------------- thresholds
    def set_threshold(self, warehouse_id, product_id, threshold):
        if not isinstance(threshold, int) or threshold < 0:
            raise ValidationError("threshold must be a non-negative integer")
        now = _now()
        with self.db.lock:
            self._ensure_warehouse_product(warehouse_id, product_id)
            row = self._get_stock_row(warehouse_id, product_id)
            if row is None:
                self.db.conn.execute(
                    "INSERT INTO stock_items(warehouse_id,product_id,quantity,version,threshold,updated_at)"
                    " VALUES (?,?,0,1,?,?)",
                    (warehouse_id, product_id, threshold, now),
                )
            else:
                self.db.conn.execute(
                    "UPDATE stock_items SET threshold=?, updated_at=? WHERE warehouse_id=? AND product_id=?",
                    (threshold, now, warehouse_id, product_id),
                )
            self.db.conn.commit()
        return {"warehouse_id": warehouse_id, "product_id": product_id, "threshold": threshold}

    def set_default_threshold(self, value):
        if not isinstance(value, int) or value < 0:
            raise ValidationError("default_threshold must be a non-negative integer")
        with self.db.lock:
            self.db.conn.execute("UPDATE global_threshold SET default_threshold=? WHERE id=1", (value,))
            self.db.conn.commit()
        return {"default_threshold": value}

    # ------------------------------------------------------------- alerts
    def _resolve_active_alerts(self, warehouse_id, product_id):
        self.db.conn.execute(
            "UPDATE alerts SET status='RESOLVED', resolved_at=? WHERE warehouse_id=? AND product_id=? AND status='ACTIVE'",
            (_now(), warehouse_id, product_id),
        )

    def _evaluate_alert(self, warehouse_id, product_id, quantity, threshold):
        if threshold is None:
            self._resolve_active_alerts(warehouse_id, product_id)
            return False
        if quantity < threshold:
            existing = self.db.conn.execute(
                "SELECT id FROM alerts WHERE warehouse_id=? AND product_id=? AND status='ACTIVE'",
                (warehouse_id, product_id),
            ).fetchone()
            if not existing:
                aid, now = _new_id(), _now()
                self.db.conn.execute(
                    "INSERT INTO alerts(id,warehouse_id,product_id,threshold,quantity_at_trigger,"
                    "status,created_at,resolved_at) VALUES (?,?,?,?,?,'ACTIVE',?,NULL)",
                    (aid, warehouse_id, product_id, threshold, quantity, now),
                )
                self.event_bus.publish("low_stock_alert", {
                    "alert_id": aid, "warehouse_id": warehouse_id, "product_id": product_id,
                    "quantity": quantity, "threshold": threshold,
                })
                self.metrics.inc("alerts_triggered_total")
                logger.info("low stock alert triggered id=%s wh=%s product=%s qty=%s threshold=%s",
                            aid, warehouse_id, product_id, quantity, threshold)
            return True
        self._resolve_active_alerts(warehouse_id, product_id)
        return False

    def list_alerts(self, status=None):
        with self.db.lock:
            if status:
                rows = self.db.conn.execute(
                    "SELECT * FROM alerts WHERE status=? ORDER BY created_at DESC", (status,)
                ).fetchall()
            else:
                rows = self.db.conn.execute("SELECT * FROM alerts ORDER BY created_at DESC").fetchall()
        return [dict(r) for r in rows]

    def resolve_alert(self, alert_id):
        with self.db.lock:
            row = self.db.conn.execute("SELECT * FROM alerts WHERE id=?", (alert_id,)).fetchone()
            if not row:
                raise NotFoundError(f"alert {alert_id} not found")
            if row["status"] == "ACTIVE":
                now = _now()
                self.db.conn.execute(
                    "UPDATE alerts SET status='RESOLVED', resolved_at=? WHERE id=?", (now, alert_id)
                )
                self.db.conn.commit()
                resolved_at = now
            else:
                resolved_at = row["resolved_at"]
        return {"id": alert_id, "status": "RESOLVED", "resolved_at": resolved_at}

    # --------------------------------------------------------------- audit
    def get_history(self, warehouse_id, product_id):
        with self.db.lock:
            self._ensure_warehouse_product(warehouse_id, product_id)
            rows = self.db.conn.execute(
                "SELECT id,delta,resulting_quantity,reason,actor,created_at FROM stock_adjustments"
                " WHERE warehouse_id=? AND product_id=? ORDER BY created_at DESC",
                (warehouse_id, product_id),
            ).fetchall()
        return [dict(r) for r in rows]

    # ---------------------------------------------------------- idempotency
    def get_idempotent_response(self, key):
        if not key:
            return None
        with self.db.lock:
            row = self.db.conn.execute(
                "SELECT * FROM idempotency_keys WHERE key=?", (key,)
            ).fetchone()
        return dict(row) if row else None

    def store_idempotent_response(self, key, request_hash, status, body):
        if not key:
            return
        with self.db.lock:
            try:
                self.db.conn.execute(
                    "INSERT INTO idempotency_keys(key,request_hash,response_body,response_status,created_at)"
                    " VALUES (?,?,?,?,?)",
                    (key, request_hash, json.dumps(body), status, _now()),
                )
                self.db.conn.commit()
            except sqlite3.IntegrityError:
                pass

"""HTTP API layer: stdlib http.server routing, auth enforcement,
JSON (de)serialization and idempotency handling for the adjust endpoint.
"""
import hashlib
import json
import logging
import re
import time
from http.server import BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

from .auth import resolve_role, role_allows
from .service import NotFoundError, ValidationError, ConflictError

logger = logging.getLogger("inventory")

# (method, compiled regex, handler suffix, required role or None)
ROUTES = [
    ("POST", re.compile(r"^/warehouses$"), "create_warehouse", "WRITE"),
    ("GET", re.compile(r"^/warehouses$"), "list_warehouses", "READ"),
    ("GET", re.compile(r"^/warehouses/(?P<warehouse_id>[^/]+)/stock$"), "list_stock_by_warehouse", "READ"),
    ("GET", re.compile(r"^/warehouses/(?P<warehouse_id>[^/]+)$"), "get_warehouse", "READ"),
    ("POST", re.compile(r"^/products$"), "create_product", "WRITE"),
    ("GET", re.compile(r"^/products$"), "list_products", "READ"),
    ("GET", re.compile(r"^/products/(?P<product_id>[^/]+)/stock$"), "list_stock_by_product", "READ"),
    ("GET", re.compile(r"^/products/(?P<product_id>[^/]+)$"), "get_product", "READ"),
    ("POST", re.compile(r"^/stock/adjust$"), "adjust_stock", "WRITE"),
    ("POST", re.compile(r"^/stock$"), "add_stock", "WRITE"),
    ("GET", re.compile(r"^/stock/(?P<warehouse_id>[^/]+)/(?P<product_id>[^/]+)/history$"), "get_history", "READ"),
    ("GET", re.compile(r"^/stock/(?P<warehouse_id>[^/]+)/(?P<product_id>[^/]+)$"), "get_stock", "READ"),
    ("PUT", re.compile(r"^/thresholds/default$"), "set_default_threshold", "WRITE"),
    ("PUT", re.compile(r"^/thresholds/(?P<warehouse_id>[^/]+)/(?P<product_id>[^/]+)$"), "set_threshold", "WRITE"),
    ("GET", re.compile(r"^/alerts$"), "list_alerts", "READ"),
    ("POST", re.compile(r"^/alerts/(?P<alert_id>[^/]+)/resolve$"), "resolve_alert", "WRITE"),
]


class InventoryRequestHandler(BaseHTTPRequestHandler):
    server_version = "InventoryHTTP/1.0"

    def log_message(self, fmt, *args):
        pass  # request logging done explicitly via the "inventory" logger

    def _send_json(self, status, payload):
        body = json.dumps(payload).encode() if payload is not None else b""
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _send_text(self, status, text):
        body = text.encode()
        self.send_response(status)
        self.send_header("Content-Type", "text/plain")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _read_json(self):
        length = int(self.headers.get("Content-Length", 0) or 0)
        if length == 0:
            return {}
        raw = self.rfile.read(length)
        try:
            return json.loads(raw.decode() or "{}")
        except json.JSONDecodeError:
            raise ValidationError("invalid JSON request body")

    def _dispatch(self, method):
        start = time.time()
        path = urlparse(self.path).path
        if method == "GET" and path == "/metrics":
            self._send_text(200, self.server.metrics.render())
            return
        service = self.server.service
        metrics = self.server.metrics
        for m, pattern, handler_name, role in ROUTES:
            if m != method:
                continue
            match = pattern.match(path)
            if not match:
                continue
            if role is not None:
                api_role = resolve_role(self.server.db, self.headers)
                if api_role is None:
                    self._send_json(401, {"error": "missing or invalid API key"})
                    return
                if not role_allows(api_role, role):
                    self._send_json(403, {"error": "insufficient permissions"})
                    return
            try:
                status, body = getattr(self, "h_" + handler_name)(match.groupdict(), service)
            except ValidationError as e:
                status, body = 400, {"error": str(e)}
            except NotFoundError as e:
                status, body = 404, {"error": str(e)}
            except ConflictError as e:
                status, body = 409, {"error": str(e)}
            except Exception:
                logger.exception("unhandled error")
                status, body = 500, {"error": "internal server error"}
            self._send_json(status, body)
            metrics.inc("requests_total")
            metrics.inc(f"status_{status}_total")
            logger.info("%s %s -> %s (%.1fms)", method, path, status, (time.time() - start) * 1000)
            return
        self._send_json(404, {"error": "not found"})

    def do_GET(self):
        self._dispatch("GET")

    def do_POST(self):
        self._dispatch("POST")

    def do_PUT(self):
        self._dispatch("PUT")

    # ---------------------------------------------------------- handlers
    def h_create_warehouse(self, params, service):
        body = self._read_json()
        return 201, service.create_warehouse(body.get("name"), body.get("location"))

    def h_list_warehouses(self, params, service):
        return 200, service.list_warehouses()

    def h_get_warehouse(self, params, service):
        return 200, service.get_warehouse(params["warehouse_id"])

    def h_create_product(self, params, service):
        body = self._read_json()
        return 201, service.create_product(body.get("sku"), body.get("name"), body.get("description"))

    def h_list_products(self, params, service):
        return 200, service.list_products()

    def h_get_product(self, params, service):
        return 200, service.get_product(params["product_id"])

    def h_add_stock(self, params, service):
        body = self._read_json()
        result = service.add_stock(
            body.get("warehouse_id"), body.get("product_id"), body.get("quantity"),
            body.get("threshold"), body.get("actor", "system"), body.get("reason"),
        )
        return 201, result

    def h_adjust_stock(self, params, service):
        body = self._read_json()
        idem_key = self.headers.get("Idempotency-Key")
        request_hash = hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()
        if idem_key:
            cached = service.get_idempotent_response(idem_key)
            if cached:
                if cached["request_hash"] != request_hash:
                    raise ConflictError("idempotency key reused with a different request payload")
                return cached["response_status"], json.loads(cached["response_body"])
        result = service.adjust_stock(
            body.get("warehouse_id"), body.get("product_id"), body.get("delta"),
            body.get("actor", "system"), body.get("reason"),
        )
        status = 200
        if idem_key:
            service.store_idempotent_response(idem_key, request_hash, status, result)
        return status, result

    def h_get_stock(self, params, service):
        return 200, service.get_stock(params["warehouse_id"], params["product_id"])

    def h_list_stock_by_product(self, params, service):
        return 200, service.list_stock_by_product(params["product_id"])

    def h_list_stock_by_warehouse(self, params, service):
        return 200, service.list_stock_by_warehouse(params["warehouse_id"])

    def h_set_threshold(self, params, service):
        body = self._read_json()
        return 200, service.set_threshold(params["warehouse_id"], params["product_id"], body.get("threshold"))

    def h_set_default_threshold(self, params, service):
        body = self._read_json()
        return 200, service.set_default_threshold(body.get("default_threshold"))

    def h_list_alerts(self, params, service):
        qs = parse_qs(urlparse(self.path).query)
        status = qs.get("status", [None])[0]
        return 200, service.list_alerts(status)

    def h_resolve_alert(self, params, service):
        return 200, service.resolve_alert(params["alert_id"])

    def h_get_history(self, params, service):
        return 200, service.get_history(params["warehouse_id"], params["product_id"])

openapi: 3.0.3
info:
  title: Inventory Service API
  version: "1.0.0"
  description: >
    REST inventory service tracking stock per product/warehouse, with
    optimistic concurrency, low-stock alerts and audit history.
servers:
  - url: http://localhost:8000
security:
  - ApiKeyAuth: []
  - BearerAuth: []
components:
  securitySchemes:
    ApiKeyAuth:
      type: apiKey
      in: header
      name: X-Api-Key
    BearerAuth:
      type: http
      scheme: bearer
  schemas:
    Error:
      type: object
      properties:
        error: { type: string }
    Warehouse:
      type: object
      properties:
        id: { type: string }
        name: { type: string }
        location: { type: string }
        created_at: { type: string }
    Product:
      type: object
      properties:
        id: { type: string }
        sku: { type: string }
        name: { type: string }
        description: { type: string }
    StockItem:
      type: object
      properties:
        warehouse_id: { type: string }
        product_id: { type: string }
        quantity: { type: integer }
        version: { type: integer }
        threshold: { type: integer, nullable: true }
        updated_at: { type: string }
    Alert:
      type: object
      properties:
        id: { type: string }
        warehouse_id: { type: string }
        product_id: { type: string }
        threshold: { type: integer }
        quantity_at_trigger: { type: integer }
        status: { type: string, enum: [ACTIVE, RESOLVED] }
        created_at: { type: string }
        resolved_at: { type: string, nullable: true }
paths:
  /warehouses:
    post:
      summary: Create a warehouse
      requestBody:
        content:
          application/json:
            schema:
              type: object
              required: [name]
              properties:
                name: { type: string }
                location: { type: string }
      responses:
        "201": { description: created, content: {application/json: {schema: {$ref: "#/components/schemas/Warehouse"}}} }
        "400": { description: invalid input, content: {application/json: {schema: {$ref: "#/components/schemas/Error"}}} }
        "401": { description: unauthorized }
        "403": { description: forbidden }
    get:
      summary: List warehouses
      responses:
        "200":
          description: ok
          content:
            application/json:
              schema: { type: array, items: {$ref: "#/components/schemas/Warehouse"} }
        "401": { description: unauthorized }
  /warehouses/{warehouse_id}:
    get:
      summary: Get a warehouse
      parameters:
        - { name: warehouse_id, in: path, required: true, schema: {type: string} }
      responses:
        "200": { description: ok, content: {application/json: {schema: {$ref: "#/components/schemas/Warehouse"}}} }
        "404": { description: not found, content: {application/json: {schema: {$ref: "#/components/schemas/Error"}}} }
  /products:
    post:
      summary: Create a product/SKU
      requestBody:
        content:
          application/json:
            schema:
              type: object
              required: [sku, name]
              properties:
                sku: { type: string }
                name: { type: string }
                description: { type: string }
      responses:
        "201": { description: created, content: {application/json: {schema: {$ref: "#/components/schemas/Product"}}} }
        "400": { description: invalid input }
        "409": { description: sku already exists }
    get:
      summary: List products
      responses:
        "200":
          description: ok
          content:
            application/json:
              schema: { type: array, items: {$ref: "#/components/schemas/Product"} }
  /products/{product_id}:
    get:
      summary: Get a product
      parameters:
        - { name: product_id, in: path, required: true, schema: {type: string} }
      responses:
        "200": { description: ok, content: {application/json: {schema: {$ref: "#/components/schemas/Product"}}} }
        "404": { description: not found }
  /stock:
    post:
      summary: Add stock (create or increase quantity) for a product at a warehouse
      requestBody:
        content:
          application/json:
            schema:
              type: object
              required: [warehouse_id, product_id, quantity]
              properties:
                warehouse_id: { type: string }
                product_id: { type: string }
                quantity: { type: integer, minimum: 1 }
                threshold: { type: integer, nullable: true }
                actor: { type: string }
                reason: { type: string }
      responses:
        "201": { description: created/updated, content: {application/json: {schema: {$ref: "#/components/schemas/StockItem"}}} }
        "400": { description: invalid input }
        "404": { description: warehouse or product not found }
  /stock/adjust:
    post:
      summary: Adjust (increment/decrement) stock, idempotent via Idempotency-Key header
      parameters:
        - name: Idempotency-Key
          in: header
          required: false
          schema: { type: string }
      requestBody:
        content:
          application/json:
            schema:
              type: object
              required: [warehouse_id, product_id, delta]
              properties:
                warehouse_id: { type: string }
                product_id: { type: string }
                delta: { type: integer }
                actor: { type: string }
                reason: { type: string }
      responses:
        "200":
          description: adjusted
          content:
            application/json:
              schema:
                allOf:
                  - $ref: "#/components/schemas/StockItem"
                  - type: object
                    properties: { alert_triggered: { type: boolean } }
        "400": { description: invalid input (e.g. resulting negative stock) }
        "404": { description: stock item not found }
        "409": { description: idempotency key conflict or concurrent modification }
  /stock/{warehouse_id}/{product_id}:
    get:
      summary: Get current stock level for product at warehouse
      parameters:
        - { name: warehouse_id, in: path, required: true, schema: {type: string} }
        - { name: product_id, in: path, required: true, schema: {type: string} }
      responses:
        "200": { description: ok, content: {application/json: {schema: {$ref: "#/components/schemas/StockItem"}}} }
        "404": { description: not found }
  /products/{product_id}/stock:
    get:
      summary: Get stock levels across all warehouses for a product
      parameters:
        - { name: product_id, in: path, required: true, schema: {type: string} }
      responses:
        "200": { description: ok }
        "404": { description: product not found }
  /warehouses/{warehouse_id}/stock:
    get:
      summary: Get all stock levels within a warehouse
      parameters:
        - { name: warehouse_id, in: path, required: true, schema: {type: string} }
      responses:
        "200": { description: ok }
        "404": { description: warehouse not found }
  /thresholds/{warehouse_id}/{product_id}:
    put:
      summary: Configure the low-stock threshold for a product/warehouse pair
      parameters:
        - { name: warehouse_id, in: path, required: true, schema: {type: string} }
        - { name: product_id, in: path, required: true, schema: {type: string} }
      requestBody:
        content:
          application/json:
            schema:
              type: object
              required: [threshold]
              properties: { threshold: { type: integer, minimum: 0 } }
      responses:
        "200": { description: ok }
        "400": { description: invalid input }
        "404": { description: not found }
  /thresholds/default:
    put:
      summary: Configure the global default low-stock threshold
      requestBody:
        content:
          application/json:
            schema:
              type: object
              required: [default_threshold]
              properties: { default_threshold: { type: integer, minimum: 0 } }
      responses:
        "200": { description: ok }
        "400": { description: invalid input }
  /alerts:
    get:
      summary: List active/resolved low-stock alerts
      parameters:
        - name: status
          in: query
          required: false
          schema: { type: string, enum: [ACTIVE, RESOLVED] }
      responses:
        "200":
          description: ok
          content:
            application/json:
              schema: { type: array, items: {$ref: "#/components/schemas/Alert"} }
  /alerts/{alert_id}/resolve:
    post:
      summary: Resolve a low-stock alert
      parameters:
        - { name: alert_id, in: path, required: true, schema: {type: string} }
      responses:
        "200": { description: resolved }
        "404": { description: alert not found }
  /stock/{warehouse_id}/{product_id}/history:
    get:
      summary: Audit trail of stock adjustments for a product/warehouse pair
      parameters:
        - { name: warehouse_id, in: path, required: true, schema: {type: string} }
        - { name: product_id, in: path, required: true, schema: {type: string} }
      responses:
        "200": { description: ok }
        "404": { description: not found }
  /metrics:
    get:
      summary: Plain-text counters (requests, adjustments, alerts)
      security: []
      responses:
        "200": { description: ok }
